problems.starterCode:
def caesar(message, shift):
    result = ""
    for char in message:
        if char.isalpha() and char.islower():
            # Shift the character
            new_char = chr((ord(char) - 97 + shift) % 26 + 97)
            result += new_char
        else:
            result += char
    return result

print(caesar("hello world", 3))

